def transform(grid):
    """Replace every cell in a constant-color rectangle at least 4x4 with 4."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    marked = [[False] * w for _ in range(h)]
    # Mark monochromatic 4x4 windows; overlapping windows recover larger patches.
    for r in range(h - 3):
        for c in range(w - 3):
            color = grid[r][c]
            if all(grid[y][x] == color
                   for y in range(r, r + 4)
                   for x in range(c, c + 4)):
                for y in range(r, r + 4):
                    for x in range(c, c + 4):
                        marked[y][x] = True
    for r in range(h):
        for c in range(w):
            if marked[r][c]:
                out[r][c] = 4
    return out
